import{_ as t,o as a,c as r,a2 as i}from"./chunks/framework.CFuv5BrO.js";const m=JSON.parse('{"title":"Reading Guide","description":"The three reading paths through the Hearth documentation, documentation conventions, site map, and source material.","frontmatter":{"title":"Reading Guide","description":"The three reading paths through the Hearth documentation, documentation conventions, site map, and source material.","outline":[2,3]},"headers":[],"relativePath":"en/guide/reading-guide.md","filePath":"en/guide/reading-guide.md","lastUpdated":1793752688000}'),n={name:"en/guide/reading-guide.md"};function o(h,e,l,d,c,s){return a(),r("div",null,[...e[0]||(e[0]=[i('<p class="eyebrow">READING GUIDE</p><h1 id="reading-guide" tabindex="-1">Reading Guide <a class="header-anchor" href="#reading-guide" aria-label="Permalink to &quot;Reading Guide&quot;">​</a></h1><p class="lead">This documentation is not a book you need to read from start to finish. First choose your role and goal, then follow a path to go deeper; when you need complete details, return to the archived full roadmap.</p><h2 id="three-reading-paths" tabindex="-1">Three Reading Paths <a class="header-anchor" href="#three-reading-paths" aria-label="Permalink to &quot;Three Reading Paths&quot;">​</a></h2><h3 id="product-and-decision-path" tabindex="-1">Product and Decision Path <a class="header-anchor" href="#product-and-decision-path" aria-label="Permalink to &quot;Product and Decision Path&quot;">​</a></h3><p>Suitable for reading when learning about the project for the first time, or when you need to decide whether to continue investing:</p><ol><li><a href="/hearth-os/en/guide/what-is-hearth.html">Understanding Hearth</a></li><li><a href="/hearth-os/en/product/definition.html">Product Definition and Boundaries</a></li><li><a href="/hearth-os/en/delivery/roadmap.html">Phased Product Roadmap</a></li><li><a href="/hearth-os/en/delivery/development-plan.html">0 to 100 Development Plan</a></li><li><a href="/hearth-os/en/delivery/risks.html">Risks and Kill Criteria</a></li></ol><h3 id="architecture-and-technical-path" tabindex="-1">Architecture and Technical Path <a class="header-anchor" href="#architecture-and-technical-path" aria-label="Permalink to &quot;Architecture and Technical Path&quot;">​</a></h3><p>Suitable for reading when preparing to start implementation, or when you need to check system boundaries:</p><ol><li><a href="/hearth-os/en/architecture/">System Design Overview</a></li><li><a href="/hearth-os/en/architecture/overview.html">Overall Architecture and Data Flow</a></li><li><a href="/hearth-os/en/architecture/domain-model.html">Domain Model and Protocols</a></li><li><a href="/hearth-os/en/architecture/gateway.html">Personal Gateway</a></li><li><a href="/hearth-os/en/architecture/control-plane.html">Control Plane and Autonomy</a></li><li><a href="/hearth-os/en/architecture/durable-execution.html">Durable Execution and Recovery</a></li><li><a href="/hearth-os/en/architecture/executor-model.html">Executor Model</a></li><li><a href="/hearth-os/en/architecture/executor-catalog.html">Executor Catalog</a></li><li><a href="/hearth-os/en/architecture/human-takeover.html">Human Takeover and Approval</a></li><li><a href="/hearth-os/en/architecture/execution-safety.html">Execution Safety</a></li><li><a href="/hearth-os/en/architecture/memory.html">Memory System</a></li><li><a href="/hearth-os/en/architecture/evolution.html">Skill Evolution</a></li><li><a href="/hearth-os/en/architecture/security-privacy.html">Security and Privacy</a></li><li><a href="/hearth-os/en/architecture/evaluation.html">Evaluation System</a></li></ol><h3 id="direct-start-path" tabindex="-1">Direct Start Path <a class="header-anchor" href="#direct-start-path" aria-label="Permalink to &quot;Direct Start Path&quot;">​</a></h3><p>Suitable for reading when you are ready to create a repository and need to find the first vertical slice:</p><ol><li><a href="/hearth-os/en/delivery/stage-0.html">Stage 0 · Definition and Prototype</a></li><li><a href="/hearth-os/en/delivery/stage-1.html">Stage 1 · Durable Kernel and MVP</a></li><li><a href="/hearth-os/en/architecture/durable-execution.html">Durable Execution and Recovery</a></li><li><a href="/hearth-os/en/architecture/executor-catalog.html">Codex Executor</a></li><li><a href="/hearth-os/en/delivery/engineering.html">Engineering Delivery and Repository Structure</a></li></ol><h2 id="documentation-conventions" tabindex="-1">Documentation Conventions <a class="header-anchor" href="#documentation-conventions" aria-label="Permalink to &quot;Documentation Conventions&quot;">​</a></h2><ul><li><strong>Stage is a capability level, not a date.</strong> Each stage can be paused, tried, and rolled back, but steps cannot be skipped.</li><li><strong>The MVP is an early exit of Stage 1.</strong> It is not a product of Stage 6, nor is it a demo with only a CLI or API.</li><li><strong>Each increment must be a vertical slice.</strong> User outcomes, interface, durable state, real execution, verification, recovery, and metrics appear together.</li><li><strong>The full version is archived.</strong> <a href="/hearth-os/en/reference/full-roadmap.html">Full Roadmap</a> retains all details; this folder is reorganized by topic, suitable for daily reading and maintenance.</li><li><strong>Chinese and English remain isomorphic.</strong> Page paths, chapter structure, and navigation hierarchy correspond one-to-one, and can be switched with one click in the upper right corner.</li></ul><h2 id="sitemap" tabindex="-1">Sitemap <a class="header-anchor" href="#sitemap" aria-label="Permalink to &quot;Sitemap&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Area</th><th>Content</th></tr></thead><tbody><tr><td><a href="/hearth-os/en/guide/">Getting Started</a></td><td>Project introduction, reading guide, status</td></tr><tr><td><a href="/hearth-os/en/product/">Product</a></td><td>Definition, design principles, task coverage</td></tr><tr><td><a href="/hearth-os/en/architecture/">System Design</a></td><td>Architecture, protocols, control plane, executors, security, memory, evolution, Token, frontend, evaluation</td></tr><tr><td><a href="/hearth-os/en/delivery/">Delivery Roadmap</a></td><td>Stage 0–6, 0–100 plan, engineering, risks, ADR</td></tr><tr><td><a href="/hearth-os/en/reference/">Reference</a></td><td>Self-development boundaries, terminology, checklist, FAQ, contribution, full archive</td></tr></tbody></table><h2 id="sources-and-maintenance" tabindex="-1">Sources and Maintenance <a class="header-anchor" href="#sources-and-maintenance" aria-label="Permalink to &quot;Sources and Maintenance&quot;">​</a></h2><p>This site is compiled from the Hearth Personal Agent OS overall roadmap, with the original material archived under <code>sources/roadmap/</code> in the repository. If there is any discrepancy between a page and the archived master document, the archived master document and the repository commit history take precedence; if you find structural issues, please submit a PR or explain in a repository Issue.</p>',19)])])}const p=t(n,[["render",o]]);export{m as __pageData,p as default};
